mapper.select:
SELECT  FROM task
WHERE id = #{id}
  AND workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})

SELECT  FROM task
WHERE workspace_id = #{workspaceId}
  AND deleted_at IS NULL
  AND board_column != 'done'
  AND remind_sent = 0
  AND remind_at IS NOT NULL
  AND remind_at <= #{now}
  AND remind_at >= #{windowStart}
ORDER BY remind_at

mapper.update:
UPDATE task SET owner = #{newName}
WHERE workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})
  AND (
    owner_user_id = #{userId}
    OR (
      owner_user_id IS NULL
      AND owner = #{oldName}
      AND NOT EXISTS (
        SELECT 1 FROM workspace_member m
        JOIN app_user u ON u.id = m.user_id
        WHERE m.workspace_id = task.workspace_id
          AND m.user_id <> #{userId}
          AND u.display_name = #{oldName}
      )
    )
  )

UPDATE task t
SET t.owner_user_id = #{userId}
WHERE t.owner = #{displayName}
  AND t.owner_user_id IS NULL
  AND t.workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})

mapper.sql:
t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL
AND t.board_column <> 'done'
AND ( LOCATE(LOWER(#{query.q}), LOWER(t.title)) > 0 OR LOCATE(LOWER(#{query.q}), LOWER(t.description)) > 0 OR LOCATE(LOWER(#{query.q}), LOWER(t.note)) > 0 OR LOCATE(LOWER(#{query.q}), LOWER(t.category)) > 0 OR EXISTS (SELECT 1 FROM requirement r WHERE r.id = t.req_id AND r.workspace_id = t.workspace_id AND LOCATE(LOWER(#{query.q}), LOWER(r.name)) > 0) OR EXISTS (SELECT 1 FROM task_tag tt JOIN tag g ON g.id = tt.tag_id WHERE tt.task_id = t.id AND tt.workspace_id = t.workspace_id AND LOCATE(LOWER(#{query.q}), LOWER(g.name)) > 0) OR EXISTS (SELECT 1 FROM attachment a WHERE a.task_id = t.id AND a.workspace_id = t.workspace_id AND LOCATE(LOWER(#{query.q}), LOWER(a.filename)) > 0) )
AND t.owner IN #{o}
AND t.priority IN #{p}
AND t.category IN #{cc}
AND (t.req_id IS NULL OR t.req_id IN #{rid})
AND t.req_id IS NULL
AND t.req_id IN #{rid}
AND EXISTS (SELECT 1 FROM task_tag tt JOIN tag g ON g.id = tt.tag_id WHERE tt.task_id = t.id AND tt.workspace_id = t.workspace_id AND g.name IN #{tg})
AND t.board_column <> 'done' AND t.due_date < #{query.today}
AND t.board_column <> 'done' AND t.due_date = #{query.today}
AND t.board_column <> 'done' AND t.due_date >= #{query.today} AND t.due_date <= DATE_ADD(#{query.today}, INTERVAL 3 DAY)
AND 1 = 0
AND ( (t.board_column <> 'done' AND t.due_date IS NOT NULL AND t.due_date <= #{query.today}) OR (t.board_column = 'doing' AND t.priority = 'P0') )
AND t.is_blocked = 1
AND t.due_date IS NULL

AND (t.start_date IS NOT NULL OR t.due_date IS NOT NULL)

  AND t.gantt_end >= #{query.from}


  AND t.gantt_start <= #{query.to}

